PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?spouse ?spouseName ?birthPlace WHERE {
  { dbr:Mok_Kwai-lan dbp:spouse ?spouse . }
  UNION
  { dbr:Mok_Kwai-lan dbo:spouse ?spouse . }

  OPTIONAL { ?spouse rdfs:label ?spouseName FILTER (lang(?spouseName) = "en") }

  OPTIONAL { ?spouse dbp:birthPlace ?birthPlace . }
  OPTIONAL { ?spouse dbo:birthPlace ?birthPlace . }
}
LIMIT 100

